sys_script_include.script:
var assetRequestUtils = Class.create();
assetRequestUtils.prototype = {
    initialize: function() {
    },

	createConfRecord : function (current) {

		// Create record in CMDB CI Tables based on Asset Type

		var cmdbTable = 'cmdb_ci_'+current.getValue('asset_type');

		gs.info('IT Asset : ' + cmdbTable);

		var grConf = new GlideRecord(cmdbTable);
		grConf.initialize();

		grConf.company = current.requestor.company;
		grConf.manufacturer = current.requestor.company;
		grConf.assigned_to = current.requestor;
		grConf.department = current.department;

		grConf.insert();

	},

    type: 'assetRequestUtils'
};
